import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.DaCm-iTo.js";const p=JSON.parse('{"title":"EmakiGem","description":"","frontmatter":{},"headers":[],"relativePath":"modules/gem/index.md","filePath":"modules/gem/index.md","lastUpdated":null}'),l={name:"modules/gem/index.md"};function i(o,t,n,s,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="emakigem" tabindex="-1">EmakiGem <a class="header-anchor" href="#emakigem" aria-label="Permalink to &quot;EmakiGem&quot;">​</a></h1><p>EmakiGem 是宝石与插槽模块，提供装备插槽、开孔器、宝石镶嵌、提取、升级、宝石共鸣与可选 Attribute 属性输出。它适合给装备添加长期养成和个性化搭配空间。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>2.6.5</code></td></tr><tr><td>主命令</td><td><code>/emakigem</code></td></tr><tr><td>别名</td><td><code>/egem</code>、<code>/eg</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>EmakiItem、EmakiAttribute、PlaceholderAPI</td></tr><tr><td>主要权限</td><td><code>emakigem.use</code>、<code>emakigem.reload</code>、<code>emakigem.admin</code>、<code>emakigem.debug</code></td></tr></tbody></table><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>插槽物品配置</td><td>定义某类装备允许拥有多少插槽、可镶嵌什么宝石。</td></tr><tr><td>插槽</td><td>装备上的宝石位置，有类型限制（attack/defense/utility/universal）。</td></tr><tr><td>开孔</td><td>解锁装备上未开放的插槽。</td></tr><tr><td>宝石</td><td>可镶嵌到插槽中的物品，提供属性、技能和外观效果。</td></tr><tr><td>提取</td><td>将已镶嵌宝石取出，可能消耗材料或有失败风险。</td></tr><tr><td>升级</td><td>提高宝石等级，解锁更强效果。</td></tr><tr><td>共鸣</td><td>当装备上的宝石满足特定组合条件时触发的额外效果。</td></tr><tr><td>gem layer</td><td>写入装备的宝石展示层，由 EmakiGem 自身的状态服务管理。</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to &quot;默认配置目录&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiGem/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── conditions/</span></span>
<span class="line"><span>├── gems/</span></span>
<span class="line"><span>├── items/</span></span>
<span class="line"><span>├── resonances/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   ├── gem/</span></span>
<span class="line"><span>│   ├── open/</span></span>
<span class="line"><span>│   └── upgrade/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p>目录说明：</p><table tabindex="0"><thead><tr><th>目录</th><th>作用</th></tr></thead><tbody><tr><td><code>gems/</code></td><td>宝石定义。</td></tr><tr><td><code>items/</code></td><td>插槽物品配置（定义哪些装备可拥有插槽）。</td></tr><tr><td><code>resonances/</code></td><td>宝石共鸣定义。</td></tr><tr><td><code>conditions/</code></td><td>镶嵌、开孔、提取、升级条件。</td></tr><tr><td><code>gui/gem/</code></td><td>镶嵌 / 提取相关 GUI。</td></tr><tr><td><code>gui/open/</code></td><td>开孔 GUI。</td></tr><tr><td><code>gui/upgrade/</code></td><td>升级 GUI。</td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to &quot;功能页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>GUI、检查、清理状态、重载和调试命令。</td></tr><tr><td><a href="./gems.html">宝石定义</a></td><td>宝石效果、费用、提取、升级和插槽类型。</td></tr><tr><td><a href="./socket-openers.html">开孔器系统</a></td><td><code>socket_openers</code>、开孔材料、插槽解锁和失败反馈。</td></tr><tr><td><a href="./inlay-chance.html">镶嵌成功率</a></td><td><code>inlay_success</code>、成功率公式和失败处理。</td></tr><tr><td><a href="./resonance.html">宝石共鸣</a></td><td>多宝石组合、共鸣效果和撤销规则。</td></tr><tr><td><a href="./templates.html">GUI 模板</a></td><td>镶嵌、开孔、升级界面配置。</td></tr><tr><td><a href="./extract.html">提取流程</a></td><td>提取费用、返还模式和效果回退。</td></tr><tr><td><a href="./process.html">镶嵌与开孔流程</a></td><td>镶嵌与开孔的执行顺序与校验点。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>EmakiGem 注册的 CoreLib 动作。</td></tr><tr><td><a href="./api.html">API</a></td><td>运行时集成与外部调用。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>可监听的 Bukkit 事件。</td></tr></tbody></table><h2 id="典型流程" tabindex="-1">典型流程 <a class="header-anchor" href="#典型流程" aria-label="Permalink to &quot;典型流程&quot;">​</a></h2><h3 id="开孔" tabindex="-1">开孔 <a class="header-anchor" href="#开孔" aria-label="Permalink to &quot;开孔&quot;">​</a></h3><ol><li>玩家打开开孔 GUI。</li><li>放入目标装备。</li><li>检查插槽物品配置、当前已开放插槽、条件和费用。</li><li>成功后解锁新插槽。</li><li>CoreLib 重建装备展示。</li></ol><h3 id="镶嵌" tabindex="-1">镶嵌 <a class="header-anchor" href="#镶嵌" aria-label="Permalink to &quot;镶嵌&quot;">​</a></h3><ol><li>玩家放入目标装备和宝石。</li><li>模块检查插槽类型、宝石 <code>socket_compatibility</code>、数量限制和条件。</li><li>扣除镶嵌费用（<code>inlay_cost</code>）。</li><li>写入宝石状态和效果（属性、技能、名称/Lore 操作）。</li><li>检查并激活满足条件的共鸣。</li><li>重建 gem layer。</li></ol><h3 id="提取" tabindex="-1">提取 <a class="header-anchor" href="#提取" aria-label="Permalink to &quot;提取&quot;">​</a></h3><ol><li>玩家选择要提取的宝石。</li><li>检查费用（<code>extract_cost</code>）、权限和条件。</li><li>成功时按 <code>extract_return</code> 配置返还宝石并清空插槽。</li><li>撤销该宝石的所有效果（通过 ItemOperationLedger 精确回退）。</li><li>重新检查共鸣状态。</li></ol><h3 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h3><ol><li>玩家在升级 GUI 中选择宝石。</li><li>检查升级材料、经济费用和等级上限。</li><li>按成功率判定结果。</li><li>成功后提升宝石等级，应用新等级的 effects。</li><li>失败时按 <code>failure_penalty</code> 处理。</li></ol><h3 id="共鸣激活" tabindex="-1">共鸣激活 <a class="header-anchor" href="#共鸣激活" aria-label="Permalink to &quot;共鸣激活&quot;">​</a></h3><ol><li>镶嵌或提取宝石后，系统自动检查所有共鸣定义。</li><li>按 <code>chain.mode</code> 和 <code>chain.pattern</code> 匹配当前装备上的宝石组合。</li><li>满足条件时激活共鸣，应用 <code>effects</code> 并执行 <code>actions</code>。</li><li>宝石被提取导致不再满足条件时，自动撤销共鸣效果。</li></ol>`,23)])])}const b=e(l,[["render",i]]);export{p as __pageData,b as default};
